/* Online campaign enrollment. Campaigns and gangs retain their canonical local IDs. */
(function(){
'use strict';
const ownerStates=new Map();
let joinState=null,ownerDialog=null,joinRouteActive=false;
const api=(path,options)=>window.AccountParity.api(path,options);
const body=(method,value)=>({method,body:JSON.stringify(value)});
const text=(en,ko,cls='')=>`<span${cls?` class="${cls}"`:''} data-i18n-ko="${esc(ko)}">${esc(en)}</span>`;
const action=(name,en,ko,kind='',extra='')=>`<button type="button" class="btn ${kind}" data-enrollment-action="${name}" ${extra}>${text(en,ko)}</button>`;
const statusLabel=status=>({pending:['Pending approval','승인 대기'],approved:['Approved','승인됨'],rejected:['Rejected','거절됨'],withdrawn:['Withdrawn','취소됨'],removed:['Removed','참가 해제됨']})[status]||['Not submitted','미신청'];
const status=status=>{const pair=statusLabel(status);return `<span class="enroll-status enroll-status-${esc(status||'none')}">${text(...pair)}</span>`};
const owned=c=>c&&(!c.remoteOwnerId||c.remoteOwnerId===window.AccountParity?.account?.id)&&c.remoteRole!=='viewer';
const codeFromPath=()=>{const match=location.pathname.match(/^\/join\/([^/]+)\/?$/);if(!match)return null;try{return decodeURIComponent(match[1])}catch{return ''}};
const ownerPath=id=>'/campaign-enrollments/'+encodeURIComponent(id);
const invitePath=code=>'/campaign-invites/'+encodeURIComponent(code);
const joinURL=code=>location.origin+'/join/'+encodeURIComponent(code);
const signedIn=()=>!!window.AccountParity?.account?.id;
const loginURL=()=>'/account?return_to='+encodeURIComponent(location.pathname+location.search);
const refreshLocale=()=>window.UKI18n?.refresh();
function errorText(error){return error?.message||'Please try again.'}
function showOwnerMessage(state,message,isError=false){if(!state.dialog?.isConnected)return;const host=state.dialog.querySelector('[data-enrollment-feedback]');host.className=isError?'enroll-feedback error':'enroll-feedback';host.setAttribute('role',isError?'alert':'status');host.textContent=message;refreshLocale()}
function markOwnerBusy(state,busy){state.busy=busy;if(state.dialog?.isConnected){state.dialog.querySelectorAll('[data-enrollment-action],#enrollment-settings input,#enrollment-settings textarea').forEach(node=>node.disabled=busy);state.dialog.setAttribute('aria-busy',String(busy))}}
function ownerRows(state){const rows=state.value.requests||[],pending=rows.filter(row=>row.status==='pending');return `<section class="enroll-requests"><div class="enroll-section-heading"><h3>${text('Join requests','참가 신청')}</h3><span class="enroll-count">${pending.length}</span>${action('owner-refresh','Refresh','새로고침','small')}</div>${!rows.length?`<p class="muted">${text('No join requests yet. Share the link to recruit players.','아직 참가 신청이 없습니다. 링크를 공유해 참가자를 모집하세요.')}</p>`:rows.slice().sort((a,b)=>(a.status==='pending'?-1:0)-(b.status==='pending'?-1:0)||String(b.createdAt).localeCompare(String(a.createdAt))).map(row=>`<article class="enroll-request"><div class="enroll-request-heading"><div><strong data-user-text>${esc(row.username)}</strong><p data-user-text>${esc(row.gangName)}</p></div>${status(row.status)}</div>${row.message?`<p class="enroll-user-note" data-user-text>${esc(row.message)}</p>`:''}<small class="muted" data-user-text>${esc(String(row.createdAt||'').slice(0,16).replace('T',' '))}</small>${row.status==='pending'?`<div class="enroll-request-actions">${action('approve','Approve','승인','primary',`data-enrollment-request="${esc(row.id)}"`)}${action('reject','Reject','거절','',`data-enrollment-request="${esc(row.id)}"`)}</div>`:''}</article>`).join('')}</section>`}
function renderOwner(state){if(!state.dialog?.isConnected||!state.value)return;const e=state.value.enrollment;state.dialog.querySelector('.modal-body').innerHTML=`<div class="enroll-manager"><p class="muted">${text('Share a recruitment link, review each request, and admit the gangs you approve.','모집 링크를 공유하고 참가 신청을 확인한 뒤 갱을 승인하세요.')}</p><form id="enrollment-settings" class="enroll-settings"><label class="enroll-toggle"><span>${text('Accept online join requests','온라인 참가 신청 받기')}</span><input type="checkbox" name="enabled" ${e.enabled?'checked':''}></label><div class="enroll-settings-grid"><label>${text('Player limit','최대 참가 인원')}<input class="field" type="number" name="maxPlayers" min="1" max="100" required value="${esc(e.maxPlayers)}"></label><div class="enroll-capacity"><strong>${esc(e.playerCount)} / ${esc(e.maxPlayers)}</strong>${text('Registered gangs','등록된 갱')}</div></div><label>${text('Public recruitment description','공개 모집 안내')}<textarea class="field" name="description" maxlength="2000" rows="3" data-user-text>${esc(e.description||'')}</textarea></label><p class="enroll-help">${text('Only the campaign name, edition, host, recruitment description and player count are public. Gang details are shown after approval.','캠페인 이름·에디션·주최자·모집 안내·참가 인원만 공개됩니다. 갱 상세 정보는 승인 후 표시됩니다.')}</p><div class="actions">${action('owner-save','Save recruitment settings','모집 설정 저장','primary')}</div></form><section class="enroll-link-section"><h3>${text('Recruitment link','모집 링크')}</h3><div class="enroll-link-row"><a class="enroll-share-link" href="${esc(joinURL(e.code))}" target="_blank" rel="noopener" data-user-text>${esc(joinURL(e.code))}</a>${action('copy','Copy link','링크 복사')}</div>${!e.enabled?`<p class="enroll-help">${text('Recruitment is paused. Enable it above before sharing the link.','현재 모집이 중지되어 있습니다. 위에서 참가 신청을 활성화하세요.')}</p>`:''}<details class="enroll-link-options"><summary>${text('Link options','링크 관리')}</summary><p class="enroll-help">${text('Replacing the link invalidates the old address. Existing requests remain.','링크를 교체하면 기존 주소는 사용할 수 없습니다. 접수된 신청은 유지됩니다.')}</p>${action('rotate','Replace recruitment link','모집 링크 교체','small')}</details></section><div data-enrollment-feedback role="status" class="enroll-feedback"></div>${ownerRows(state)}</div>`;refreshLocale();markOwnerBusy(state,state.busy)}
async function fetchOwner(state){const result=await api(ownerPath(state.id));if(!state.dialog?.isConnected)return;state.value=result;renderOwner(state)}
async function openOwner(id){const c=data.campaigns.find(row=>row.id===id);if(!owned(c))return;if(ownerDialog?.isConnected)return;showModal(text('Online Participation','온라인 참가'),`<p class="enroll-loading" role="status">${text('Loading recruitment settings…','모집 설정을 불러오는 중…')}</p>`,'Close',()=>true);const dialog=document.querySelector('.modal-bg'),closeButton=dialog.querySelector('#modal-submit');closeButton.textContent='Close';closeButton.dataset.i18nEn='Close';closeButton.dataset.i18nKo='닫기';refreshLocale();dialog.classList.add('enroll-dialog');dialog.querySelector('#modal-cancel').hidden=true;ownerDialog=dialog;const state={id,dialog,busy:true,value:null};ownerStates.set(id,state);try{if(!signedIn())throw Error('Sign in to manage online recruitment.');await window.AccountParity.ensureSynced();await fetchOwner(state)}catch(error){if(dialog.isConnected){dialog.querySelector('.modal-body').innerHTML=`<div data-enrollment-feedback class="enroll-feedback error" role="alert">${esc(errorText(error))}</div><div class="actions">${!signedIn()?`<a class="btn primary" href="${esc(loginURL())}" target="_top">${text('Sign in · Create account','로그인 · 회원가입')}</a>`:action('owner-retry','Retry','다시 시도')}</div>`;refreshLocale()}}finally{markOwnerBusy(state,false)}}
function ownerDraft(state){const form=state.dialog?.querySelector('#enrollment-settings');if(!form||!form.reportValidity())return null;return {enabled:form.elements.enabled.checked,maxPlayers:Number(form.elements.maxPlayers.value),description:form.elements.description.value}}
async function ownerAction(button){const dialog=button.closest('.enroll-dialog'),state=[...ownerStates.values()].find(value=>value.dialog===dialog);if(!state||state.busy)return;const type=button.dataset.enrollmentAction;if(type==='approve'&&window.MMRosterValidation?.ensureReviewed){const c=data.campaigns.find(row=>row.id===state.id),ids=new Set((c?.members||[]).map(row=>row.gangId)),unreviewed=data.gangs.filter(g=>ids.has(g.id)&&!g.remoteReadOnly&&(!g.remoteOwnerId||g.remoteOwnerId===window.AccountParity.account?.id)&&window.MMRosterValidation.requiresReview(g));if(unreviewed.length){for(const g of unreviewed)if(!await window.MMRosterValidation.ensureReviewed(g,'campaign-approval'))break;await openOwner(state.id);return}}if(type==='copy'){try{await navigator.clipboard.writeText(joinURL(state.value.enrollment.code));showOwnerMessage(state,window.UKI18n?.t('Link copied.')||'Link copied.')}catch{showOwnerMessage(state,window.UKI18n?.t('Copy the recruitment link shown above.')||'Copy the recruitment link shown above.')}return}if(type==='rotate'&&!button.dataset.confirm){button.dataset.confirm='yes';button.innerHTML=text('Confirm: replace link','확인: 링크 교체');return}const settings=['owner-save','rotate'].includes(type)?ownerDraft(state):null;if(['owner-save','rotate'].includes(type)&&!settings)return;markOwnerBusy(state,true);showOwnerMessage(state,'');try{await window.AccountParity.ensureSynced();if(type==='owner-save'||type==='rotate'){state.value=await api(ownerPath(state.id),body('PUT',{...settings,...(type==='rotate'?{rotateCode:true}:{})}));renderOwner(state);showOwnerMessage(state,window.UKI18n?.t('Settings saved.')||'Settings saved.')}else if(type==='approve'||type==='reject'){if(type==='approve'){const published=await window.AccountParity.publishCampaign(state.id,{expectedRevision:state.value.enrollment.revision,refresh:false});state.value.enrollment.revision=published.revision;}await api(ownerPath(state.id)+'/requests/'+encodeURIComponent(button.dataset.enrollmentRequest)+'/respond',body('POST',{action:type,revision:state.value.enrollment.revision}));if(type==='approve')await window.AccountParity.refreshShared(state.id,{navigate:false,preserveOwnerEdits:true});await fetchOwner(state);showOwnerMessage(state,window.UKI18n?.t(type==='approve'?'Request approved.':'Request rejected.')||(type==='approve'?'Request approved.':'Request rejected.'))}else await fetchOwner(state)}catch(error){showOwnerMessage(state,errorText(error),true);if(!state.value&&dialog.isConnected&&!dialog.querySelector('[data-enrollment-action="owner-retry"]'))dialog.querySelector('.modal-body').insertAdjacentHTML('beforeend',action('owner-retry','Retry','다시 시도'));}finally{markOwnerBusy(state,false)}}
function eligibleGangs(invite){const uid=window.AccountParity?.account?.id;return (data.gangs||[]).filter(g=>String(g.edition||'').toUpperCase()===String(invite.edition||'').toUpperCase()&&!g.remoteReadOnly&&(!g.remoteOwnerId||g.remoteOwnerId===uid))}
function joinDraft(){const form=document.querySelector('#enrollment-join-form');if(form&&joinState){joinState.draft={gangId:form.elements.gangId.value,message:form.elements.message.value}}}
function joinBody(state){if(state.loading&&!state.value)return `<div class="enroll-empty" role="status">${text('Loading campaign…','캠페인을 불러오는 중…')}</div>`;if(!state.value)return `<div class="enroll-empty"><h1>${text('Campaign link unavailable','캠페인 링크를 열 수 없습니다')}</h1><p class="enroll-feedback error" role="alert">${esc(state.error)}</p>${action('join-retry','Retry','다시 시도')}</div>`;const {invite,request}=state.value,gangs=eligibleGangs(invite),limit=Number(invite.maxPlayers),full=Number(invite.playerCount)>=limit;let form='';if(request&&!state.reapply){const pair=statusLabel(request.status);form=`<section class="enroll-join-status"><h2>${text(...pair)}</h2><div class="enroll-request-heading"><strong data-user-text>${esc(request.gangName)}</strong>${status(request.status)}</div>${request.message?`<p class="enroll-user-note" data-user-text>${esc(request.message)}</p>`:''}<p>${request.status==='pending'?text('The host will review your application. Refresh this page to check its status.','주최자가 신청을 확인합니다. 새로고침하여 승인 상태를 확인하세요.'):request.status==='approved'?text('Your gang has joined the campaign. You can now view the shared campaign.','갱이 캠페인에 등록되었습니다. 공유 캠페인을 열어볼 수 있습니다.'):request.status==='withdrawn'?text('You withdrew this request. You may apply again while recruitment is open.','취소한 신청입니다. 모집 중이라면 다시 신청할 수 있습니다.'):request.status==='removed'?text('Your participation has ended. You may apply again while recruitment is open.','캠페인 참가가 해제되었습니다. 모집 중이라면 다시 신청할 수 있습니다.'):text('This application was not accepted. Contact the host if you need more information.','이번 신청은 승인되지 않았습니다. 자세한 내용은 주최자에게 확인하세요.')}</p><div class="actions">${request.status==='pending'?action('withdraw','Withdraw request','신청 취소','danger'):request.status==='approved'?action('open-campaign','Open campaign','캠페인 열기','primary'):invite.canApply&&invite.enabled&&!full?action('apply-again','Apply again','다시 신청','primary'):''}${action('join-retry','Refresh status','상태 새로고침')}</div></section>`}else if(!invite.enabled||full)form=`<div class="enroll-empty"><h2>${full?text('Campaign is full','참가 인원이 마감되었습니다'):text('Recruitment is paused','현재 모집이 중지되었습니다')}</h2><p>${text('Contact the host or check back later.','주최자에게 문의하거나 나중에 다시 확인하세요.')}</p>${action('join-retry','Refresh','새로고침')}</div>`;else if(!invite.canApply)form=`<div class="enroll-empty"><h2>${text('Check your campaign access','캠페인 참여 상태를 확인하세요')}</h2><p>${text('You already own this campaign or have an invitation. Check your account for access.','이미 소유한 캠페인이거나 초대가 있습니다. 계정에서 참여 상태를 확인하세요.')}</p><div class="actions">${(data.campaigns||[]).some(c=>c.id===invite.campaignId)?action('open-campaign','Open campaign','캠페인 열기','primary'):''}<a class="btn" href="/account">${text('Open account','계정 열기')}</a></div></div>`;else if(!signedIn())form=`<section class="enroll-signin"><h2>${text('Bring your gang to the campaign','내 갱으로 캠페인에 참가하기')}</h2><p>${text('Sign in to choose a gang and send a join request to the host.','로그인한 뒤 내 갱을 선택하고 주최자에게 참가 신청을 보내세요.')}</p><a class="btn primary" href="${esc(loginURL())}" target="_top">${text('Sign in · Create account','로그인 · 회원가입')}</a></section>`;else if(!window.AccountParity.ready)form=`<div class="enroll-empty"><p>${text('Your account records are connecting.','계정 기록에 연결하고 있습니다.')}</p>${action('join-retry','Retry connection','연결 다시 시도')}</div>`;else if(!gangs.length)form=`<div class="enroll-empty"><h2>${text('Create a compatible gang first','같은 에디션의 갱이 필요합니다')}</h2><p>${text('You need your own synced gang in this campaign’s edition to apply.','이 캠페인과 같은 에디션으로 만든 본인 갱을 계정에 저장한 뒤 신청하세요.')}</p><a class="btn primary" href="/">${text('Go to my gangs','내 갱으로 이동')}</a>${action('join-retry','Refresh gangs','갱 목록 새로고침')}</div>`;else form=`<form id="enrollment-join-form" class="enroll-join-form"><h2>${text('Request to join','참가 신청')}</h2><label>${text('Your gang','참가할 내 갱')}<select class="field" name="gangId" required>${gangs.map(g=>`<option value="${esc(g.id)}" ${state.draft.gangId===g.id?'selected':''} data-user-text>${esc(g.name)}</option>`).join('')}</select></label><label>${text('Message to the host (optional)','주최자에게 남길 말 (선택)')}<textarea class="field" name="message" maxlength="1000" rows="3" data-user-text>${esc(state.draft.message||'')}</textarea></label><p class="enroll-help">${text('Your gang name, roster and this message are shared with the host. Approval gives you access to view the campaign. If you change your gang while waiting, withdraw and apply again.','갱 이름·명단·메시지가 주최자에게 공유됩니다. 승인되면 캠페인을 열람할 수 있습니다. 대기 중 갱을 변경했다면 신청을 취소하고 다시 신청하세요.')}</p><button type="submit" class="btn primary" data-enrollment-action="join-submit">${text('Send join request','참가 신청 보내기')}</button></form>`;return `<div class="enroll-join-heading"><div class="eyebrow">${text('CAMPAIGN RECRUITMENT','캠페인 모집')}</div><h1 data-user-text>${esc(invite.name)}</h1><p class="enroll-host"><span data-user-text>${esc(invite.ownerName)}</span> · <span data-user-text>${esc(invite.edition)}</span></p><div class="enroll-public-meta"><span>${text('Registered gangs','등록된 갱')} <strong>${esc(invite.playerCount)} / ${esc(invite.maxPlayers)}</strong></span><span class="enroll-status ${invite.enabled?'enroll-status-approved':''}">${invite.enabled?text('Recruiting','모집 중'):text('Paused','모집 중지')}</span></div>${invite.description?`<p class="enroll-public-description" data-user-text>${esc(invite.description)}</p>`:''}</div><div class="enroll-join-content">${form}<p class="enroll-feedback ${state.error?'error':''}" data-enrollment-join-feedback role="${state.error?'alert':'status'}">${esc(state.error||state.notice||'')}</p></div>`}
function renderJoin(){const code=codeFromPath();if(code===null){joinRouteActive=false;return false}if(!joinState||joinState.code!==code){joinState={code,loading:false,busy:false,value:null,error:'',notice:'',draft:{gangId:'',message:''}};queueMicrotask(()=>loadJoin(joinState))}else if(!joinRouteActive)queueMicrotask(()=>loadJoin(joinState));joinRouteActive=true;joinDraft();const state=joinState,active=document.activeElement,selection=active?.closest('#enrollment-join-form')?{name:active.name,start:active.selectionStart,end:active.selectionEnd}:null;document.querySelector('#app').innerHTML=`<div class="enroll-public-shell"><header class="enroll-public-header"><a class="enroll-public-brand" href="/"><img src="/brand/underhive-korea-192.png" width="44" height="44" alt=""><span>${text('Underhive Korea','언더하이브 코리아')}</span></a><div class="uk-language-switch" role="group" aria-label="Language"><button type="button" data-uk-locale-toggle="ko" aria-pressed="${window.UKI18n?.language!=='en'}">한</button><button type="button" data-uk-locale-toggle="en" aria-pressed="${window.UKI18n?.language==='en'}">EN</button></div></header><main class="enroll-public-main"><article class="enroll-public-card" aria-busy="${state.busy||state.loading}">${joinBody(state)}</article><a class="enroll-home-link" href="/">${text('Back to my workspace','내 작업 공간으로 돌아가기')} →</a></main></div>`;document.querySelectorAll('.enroll-public-card [data-enrollment-action],#enrollment-join-form input,#enrollment-join-form select,#enrollment-join-form textarea').forEach(node=>node.disabled=state.busy||state.loading);refreshLocale();if(selection){const replacement=document.querySelector(`#enrollment-join-form [name="${selection.name}"]`);if(replacement&&!replacement.disabled){replacement.focus({preventScroll:true});if(selection.start!==null&&replacement.setSelectionRange)replacement.setSelectionRange(selection.start,selection.end)}}return true}
async function loadJoin(state){if(state.loading)return;state.loading=true;state.error='';if(codeFromPath()===state.code)renderJoin();try{const value=await api(invitePath(state.code));if(joinState!==state)return;state.value=value;state.reapply=false}catch(error){if(joinState!==state)return;state.error=errorText(error)}finally{state.loading=false;if(joinState===state&&codeFromPath()===state.code)renderJoin()}}
async function joinAction(type){const state=joinState;if(!state||state.busy||state.loading)return;joinDraft();if(type==='apply-again'){state.reapply=true;state.error='';renderJoin();return}if(type==='join-submit'){const form=document.querySelector('#enrollment-join-form');if(!form||!form.reportValidity())return;const selected=data.gangs.find(g=>g.id===state.draft.gangId);if(window.MMRosterValidation?.ensureReviewed){state.busy=true;let checked;try{checked=await window.MMRosterValidation.ensureReviewed(selected,'campaign-enrollment')}finally{state.busy=false}if(!checked){renderJoin();return}}}state.busy=true;state.error='';renderJoin();try{if(type==='join-submit'){await window.AccountParity.ensureSynced();const result=await api(invitePath(state.code)+'/requests',body('POST',{gangId:state.draft.gangId,message:state.draft.message}));state.value.request=result.request;state.reapply=false;state.notice=''}else if(type==='withdraw'){await api(invitePath(state.code)+'/requests',{method:'DELETE'});state.value.request=null;state.notice='';await loadJoin(state)}else if(type==='open-campaign'){const id=state.value.invite.campaignId;await window.AccountParity.openShared(id);history.pushState({},'','/campaigns/'+encodeURIComponent(data.selectedCampaign||id));render();return}else{if(signedIn()&&!window.AccountParity.ready)await window.AccountParity.ensureSynced();await loadJoin(state)}}catch(error){state.error=errorText(error)}finally{state.busy=false;if(codeFromPath()===state.code)renderJoin()}}
const previousRender=render;render=function(...args){if(renderJoin())return;const result=previousRender.apply(this,args);const c=typeof campaign==='function'?campaign():null;if(data.view==='campaign'&&owned(c)){if(!document.querySelector('[data-enrollment-open]')){const controls=`<div class="actions enroll-campaign-actions"><button type="button" class="btn small enroll-open" data-enrollment-open="${esc(c.id)}">${text('Online Participation','온라인 참가')}</button></div>`;const card=document.querySelector('.entity-card'),content=document.querySelector('.content');if(card)card.querySelector('.entity-head').insertAdjacentHTML('afterend',controls);else content?.insertAdjacentHTML('afterbegin',controls)}refreshLocale()}return result};
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-enrollment-open],[data-enrollment-action]');if(!button)return;event.preventDefault();if(button.disabled)return;if(button.dataset.enrollmentOpen){openOwner(button.dataset.enrollmentOpen);return}if(button.closest('.enroll-dialog'))ownerAction(button);else joinAction(button.dataset.enrollmentAction)});
document.addEventListener('submit',event=>{if(event.target.id==='enrollment-join-form'){event.preventDefault();joinAction('join-submit')}else if(event.target.id==='enrollment-settings'){event.preventDefault();const button=event.target.querySelector('[data-enrollment-action="owner-save"]');if(button)ownerAction(button)}});
document.addEventListener('input',event=>{if(event.target.closest?.('#enrollment-join-form'))joinDraft()});document.addEventListener('change',event=>{if(event.target.closest?.('#enrollment-join-form'))joinDraft()});
window.addEventListener('uk:languagechange',()=>{if(codeFromPath()!==null)renderJoin()});
window.CampaignEnrollment={open:openOwner,refresh:()=>joinState?loadJoin(joinState):Promise.resolve(),isJoinRoute:()=>codeFromPath()!==null};
})();
